import {programs,seed,evaluate,compare,makePacket,validateState,demoDate} from './engine.js';
let state=seed(),selected='housing',asOf=demoDate,pending=null;
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={ready:'Checks satisfied',review:'Needs review',rule_not_met:'Demo rule not met',pass:'Satisfied',consent_required:'Consent needed',missing:'Missing evidence',stale:'Refresh evidence',conflict:'Conflicting records'};
function badge(status){return `<span class="badge ${['pass','ready'].includes(status)?'':status==='consent_required'?'blocked':'warn'}">${esc(labels[status])}</span>`;}
let noticeTimer;function notify(msg){$('notice').textContent=msg;$('notice').style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').style.display='none',6000);}
function log(action){state.events.push({at:new Date().toISOString(),action});renderEvents();}
function renderEvents(){$('events').innerHTML=state.events.length?[...state.events].reverse().map(e=>`<div class="event"><time>${esc(new Date(e.at).toLocaleTimeString())}</time><p>${esc(e.action)}</p></div>`).join(''):'No actions yet. Try a scenario, change the evaluation date, or withdraw consent.';}
function render(){
  const results=programs.map(p=>evaluate(state,p,asOf));
  const checks=results.flatMap(r=>r.checks);const unique=new Set(checks.filter(c=>c.status==='pass').flatMap(c=>c.evidenceIds));
  const reused=[...unique].filter(id=>results.filter(r=>r.checks.some(c=>c.status==='pass'&&c.evidenceIds.includes(id))).length>1).length;
  $('metrics').innerHTML=[['Evidence records',state.evidence.length,'in this session'],['Program checks',checks.length,'traceable'],['Reused records',reused,'across programs'],['Need attention',checks.filter(c=>c.status!=='pass').length,'check-level issues']].map(([label,note,sub])=>`<div class="metric"><span>${label}</span><strong>${note}</strong><small>${sub}</small></div>`).join('');
  $('programs').innerHTML=programs.map((p,i)=>`<button class="program-card ${p.id===selected?'selected':''}" data-program="${p.id}"><span class="num">0${i+1} / ${p.version}</span><h3>${p.name} ↗</h3>${badge(results[i].status)}</button>`).join('');
  document.querySelectorAll('[data-program]').forEach(b=>b.onclick=()=>{selected=b.dataset.program;render();});
  graph(results);detail();renderEvents();
}
function graph(results){
  // SVG is generated only from escaped labels and fixed coordinates.
  const src=[{id:'monthlyIncome',label:'Income record',sub:'Monthly earnings'},{id:'city',label:'Residency record',sub:'Service area'},{id:'enrolled',label:'Enrollment record',sub:'Student status'}];
  let paths='';for(let i=0;i<src.length;i++)for(let j=0;j<programs.length;j++)if(programs[j].rules.some(r=>r.field===src[i].id)){const c=results[j].checks.find(r=>r.field===src[i].id);paths+=`<path d="M 202 ${38+i*78} C 275 ${38+i*78},275 ${38+j*78},350 ${38+j*78}" fill="none" stroke="${c.status==='pass'?'#80ad9e':'#cfb49c'}" stroke-width="1.5" ${c.status==='consent_required'?'stroke-dasharray="4 5"':''}/>`;}
  $('graph').innerHTML=`<svg viewBox="0 0 900 245" role="img" aria-label="Evidence dependency map. Income supports all three programs. Residency supports housing and transit. Enrollment supports learning.">${paths}${results.map((r,i)=>`<path d="M 550 ${38+i*78} H 675" stroke="#d3dddf"/><circle cx="650" cy="${38+i*78}" r="3" fill="#a9b9bd"/>`).join('')}${src.map((s,i)=>`<rect x="0" y="${10+i*78}" width="202" height="56" rx="7" fill="#f7f9fa" stroke="#e0e6e8"/><text x="16" y="${33+i*78}" font-size="12" fill="#18303a">${s.label}</text><text x="16" y="${51+i*78}" font-size="9" fill="#697982">${s.sub}</text>`).join('')}${results.map((r,i)=>`<rect x="350" y="${10+i*78}" width="200" height="56" rx="7" fill="#fff" stroke="#d1dedc"/><text x="367" y="${33+i*78}" font-size="12" fill="#18303a">${esc(r.program)}</text><text x="367" y="${51+i*78}" font-size="9" fill="#697982">${r.checks.filter(c=>c.status==='pass').length} / ${r.checks.length} checks satisfied</text><rect x="675" y="${19+i*78}" width="220" height="36" rx="18" fill="${r.status==='ready'?'#edf4f0':'#f9eee3'}"/><text x="785" y="${42+i*78}" font-size="11" text-anchor="middle" fill="${r.status==='ready'?'#2e7965':'#9a5f2e'}">${esc(labels[r.status])}</text>`).join('')}</svg>`;
}
function detail(){const p=programs.find(p=>p.id===selected),r=evaluate(state,p,asOf),grant=state.consents.find(c=>c.programId===p.id);const active=grant&&!grant.revoked&&grant.expiresAt>=asOf&&grant.purpose===p.purpose;
  $('detail').innerHTML=`<div class="detail-header"><div><p class="eyebrow">INSPECT / ${esc(p.version)}</p><h2>${p.name}</h2></div><div class="actions"><button class="secondary" id="consent">${active?'Withdraw consent':'Grant demo consent'}</button><button class="primary" id="export" ${r.status!=='ready'?'disabled':''}>Download minimal packet ↓</button></div></div><table><thead><tr><th>CHECK</th><th>EVIDENCE</th><th>STATUS</th><th>EXPLANATION</th></tr></thead><tbody>${r.checks.map(c=>`<tr><td>${esc(c.label)}<div class="check-meta">${esc(c.requirement)} · ≤ ${c.maxAgeDays} days</div></td><td>${c.evidenceIds.length?c.evidenceIds.map(id=>{const e=state.evidence.find(x=>x.id===id);return `${esc(e.title)}<div class="check-meta">${esc(e.issuedAt)} · ${esc(id)}</div>`;}).join(''):'Withheld or absent'}</td><td>${badge(c.status)}</td><td>${esc(c.reason)}</td></tr>`).join('')}</tbody></table><div class="detail-note">Purpose: <strong>${esc(p.purpose)}</strong>. ${active?'Demo consent expires '+esc(grant.expiresAt)+'.':'No current demo consent.'} Packets include required fields and source metadata only. No raw documents, account numbers, or street addresses.</div>`;
  $('consent').onclick=()=>{let c=state.consents.find(c=>c.programId===p.id);if(active){c.revoked=true;}else{if(c)state.consents.splice(state.consents.indexOf(c),1);state.consents.push({programId:p.id,purpose:p.purpose,fields:p.rules.map(r=>r.field),expiresAt:'2099-12-31',revoked:false});}pending=null;$('apply').disabled=true;log(`${active?'Withdrew':'Granted'} synthetic consent for ${p.name}; future exports recomputed.`);render();notify(active?'Consent withdrawn. Future exports are blocked; previous downloads cannot be retracted.':'Demo consent granted for the displayed purpose and fields.');};
  $('export').onclick=()=>{try{const packet=makePacket(state,p,asOf),url=URL.createObjectURL(new Blob([JSON.stringify(packet,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`claimweave-${p.id}-packet.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);log(`Downloaded minimal synthetic packet for ${p.name} (${packet.claims.length} claims).`);notify('Synthetic packet downloaded. Nothing was sent to an agency.');}catch(e){notify(e.message);}};
}
function show(view){document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const info={workspace:['One record.<br>Every dependency.','See what an application check relies on, what changed,<br>and exactly what needs a second look.'],scenarios:['Change one thing.<br>Trace the effect.','Reproduce a policy or evidence change before it<br>reaches an application workflow.'],audit:['Every action.<br>In context.','A readable record of this demo session.'],research:['A focused question.<br>An honest scope.','Research, closest alternatives, and what this prototype actually does.']}[view];$('page-title').innerHTML=info[0];$('page-description').innerHTML=info[1];}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));
$('asof').onchange=e=>{if(!e.target.value)return;asOf=e.target.value;pending=null;$('apply').disabled=true;log(`Evaluation date changed to ${asOf}.`);render();};
$('scenario').onchange=()=>{pending=null;$('apply').disabled=true;};
$('run').onclick=()=>{const kind=$('scenario').value;const base=programs.find(p=>p.id===(kind==='missing'?'learning':'housing'));let next=structuredClone(state),policy=structuredClone(base);
  if(kind==='threshold'){policy.rules[0].value=2000;policy.version='demo-2-income';}
  if(kind==='freshness'){policy.rules[0].maxAgeDays=7;policy.version='demo-2-freshness';}
  if(kind==='conflict')next.evidence.push({id:'conflict-'+Date.now(),title:'Synthetic competing payroll',source:'Demo secondary payroll',issuedAt:asOf,fields:{monthlyIncome:3100}});
  if(kind==='revoke'){const c=next.consents.find(c=>c.programId==='housing');if(c)c.revoked=true;}
  if(kind==='missing')next.evidence=next.evidence.filter(e=>!Object.hasOwn(e.fields,'enrolled'));
  const a=evaluate(state,base,asOf),b=evaluate(next,policy,asOf);const diff=kind==='threshold'||kind==='freshness'?compare(state,base,policy,asOf).changes:b.checks.filter(c=>JSON.stringify(c)!==JSON.stringify(a.checks.find(x=>x.field===c.field))).map(c=>({field:c.field,before:a.checks.find(x=>x.field===c.field),after:c}));
  $('comparison').innerHTML=`<p class="eyebrow">${esc(base.name)} / ${diff.length} CHECK CHANGES</p><h2>${esc($('scenario').selectedOptions[0].textContent)}</h2><div class="compare-sides"><div class="compare-side"><p>BASELINE · ${esc(a.policyVersion)}</p>${badge(a.status)}</div><div class="compare-side"><p>SCENARIO · ${esc(b.policyVersion)}</p>${badge(b.status)}</div></div>${diff.length?diff.map(d=>`<div class="change-row"><strong>${esc(d.after.label)}</strong><p>${badge(d.before.status)} → ${badge(d.after.status)}</p><p>${esc(d.after.reason)}</p><span class="check-meta">${esc(d.before.requirement)} → ${esc(d.after.requirement)} · freshness ${d.before.maxAgeDays} → ${d.after.maxAgeDays} days</span></div>`).join(''):'No checks change under the current baseline.'}<p class="small">Comparison only. All rules are fictional; this is not a benefit eligibility result.</p>`;
  pending=['conflict','revoke','missing'].includes(kind)?next:null;$('apply').disabled=!pending;log(`Compared scenario: ${$('scenario').selectedOptions[0].textContent}.`);
};
$('apply').onclick=()=>{if(!pending)return;const events=state.events;state=pending;state.events=events;pending=null;$('apply').disabled=true;log('Applied synthetic evidence/consent scenario to workspace.');render();show('workspace');notify('Scenario applied. Use Reset demo to restore the original records.');};
$('reset').onclick=()=>{state=seed();asOf=demoDate;selected='housing';pending=null;$('asof').value=asOf;$('apply').disabled=true;$('comparison').innerHTML='<h2>Baseline restored.</h2><p>Run a new comparison.</p>';log('Restored original synthetic demo records.');render();notify('Demo reset. No data persists across reloads.');};
$('import').onclick=()=>$('file').click();
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('Demo import must be under 100 KB.');const raw=validateState(JSON.parse(await file.text()));state={schemaVersion:1,evidence:structuredClone(raw.evidence),consents:structuredClone(raw.consents),events:[]};pending=null;$('apply').disabled=true;log('Imported synthetic JSON fixture; all checks recalculated.');render();notify('Fixture loaded in browser memory only.');}catch(err){notify('Import rejected: '+err.message);}finally{e.target.value='';}};
render();
import('./accounts.js').then(m=>m.mount(()=>({state:structuredClone(state),asOf}),w=>{state=w?validateState(structuredClone(w.state)):seed();asOf=w?.asOf||demoDate;pending=null;$('asof').value=asOf;$('apply').disabled=true;render();})).catch(()=>notify('Account tools could not load.'));
import('./lab.js').then(m=>m.mount(()=>({state:structuredClone(state),asOf}),log)).catch(()=>notify('Repair tools could not load. Reload the page to retry.'));
